from collections import deque

def bfs_order(graph, start):
    order = [start]
    seen = {start}
    queue = deque([start])
    while queue:
        v = queue.popleft()
        for w in graph.get(v, []):
            if w not in seen:
                seen.add(w)
                order.append(w)
                queue.append(w)
    return order

def topo_order(deps):
    remaining = {task: set(d) for task, d in deps.items()}
    order = []
    while remaining:
        task = min(t for t, d in remaining.items() if not d)
        order.append(task)
        del remaining[task]
        for d in remaining.values():
            d.discard(task)
    return order

