def decode_repeats(s):
    stack = [["", 1]]
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "[":
            stack.append(["", num])
            num = 0
        elif ch == "]":
            text, count = stack.pop()
            stack[-1][0] += text * count
        else:
            stack[-1][0] += ch
