def smallest_with_digit_product(n):
    if n < 10:
        return n
    digits = []
    for d in range(9, 1, -1):
        while n % d == 0:
            digits.append(d)
            n //= d
    if n != 1:
        return -1
    return int("".join(map(str, sorted(digits))))

def min_squares_sum(n):
    best = [0] + [n] * n
    for i in range(1, n + 1):
        j = 1
        while j * j <= i:
            best[i] = min(best[i], best[i - j * j] + 1)
            j += 1
    return best[n]

def partition_count(n):
    ways = [1] + [0] * n
    for part in range(1, n + 1):
        for total in range(part, n + 1):
            ways[total] += ways[total - part]
    return ways[n]

def next_same_popcount(n):
    target = bin(n).count("1")
    m = n + 1
    while bin(m).count("1") != target:
        m += 1
    return m

def min_swaps_binary_sort(bits):
    swaps = 0
    ones = 0
    for b in bits:
        if b == 1:
            ones += 1
        else:
            swaps += ones
    return swaps

def run_stack_commands(commands):
    stack = []
    for command in commands:
        if command == "pop":
            if stack:
                stack.pop()
        else:
            stack.append(int(command.split()[1]))
    return stack

def eval_rpn(tokens):
    stack = []
    for tok in tokens:
        if tok in ("+", "-", "*", "/"):
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                q = abs(a) // abs(b)
                stack.append(q if (a >= 0) == (b > 0) else -q)
        else:
            stack.append(int(tok))
    return stack[0]

def fold_sums(nums):
    n = len(nums)
    result = [nums[i] + nums[n - 1 - i] for i in range(n // 2)]
    if n % 2:
        result.append(nums[n // 2])
    return result

