def minesweeper_annotate(board):
    rows, cols = len(board), len(board[0])
    out = []
    for r in range(rows):
        line = ""
        for c in range(cols):
            if board[r][c] == "*":
                line += "*"
            else:
                count = sum(board[rr][cc] == "*"
                            for rr in range(max(0, r - 1), min(rows, r + 2))
                            for cc in range(max(0, c - 1), min(cols, c + 2)))
                line += str(count)
        out.append(line)
    return out

from collections import deque

def grid_shortest_path(grid):
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == "#" or grid[rows - 1][cols - 1] == "#":
        return -1
    dist = {(0, 0): 0}
    queue = deque([(0, 0)])
    while queue:
        r, c = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
            return dist[(r, c)]
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "." and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                queue.append((nr, nc))
    return -1

def pascal_triangle(n):
    rows = []
    for i in range(n):
        row = [1] * (i + 1)
        for j in range(1, i):
            row[j] = rows[i - 1][j - 1] + rows[i - 1][j]
        rows.append(row)
    return rows

def group_anagrams(words):
    groups = {}
    for w in words:
        groups.setdefault("".join(sorted(w)), []).append(w)
    return list(groups.values())

def paths_avoiding_obstacles(grid):
    rows, cols = len(grid), len(grid[0])
    ways = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                ways[r][c] = 0
            elif r == 0 and c == 0:
                ways[r][c] = 1
            else:
                ways[r][c] = (ways[r - 1][c] if r > 0 else 0) + (ways[r][c - 1] if c > 0 else 0)
    return ways[rows - 1][cols - 1]

def is_prefix_free(words):
    return not any(i != j and b.startswith(a)
                   for i, a in enumerate(words) for j, b in enumerate(words))

